(()=>{
'use strict';
const engine=window.TwanovaPractice;
let s=engine.fresh(),current='agency',step=0,language='en';
const t=(en,es)=>language==='es'?es:en;
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const lesson=(en,es,helpEn,helpEs,actions)=>({en,es,helpEn,helpEs,actions});
const lessons={
agency:[
 lesson('Create sample agency','Crear agencia de práctica','Begin with fictional Summit Staffing. No account is created.','Comienza con Summit Staffing ficticia. No se crea ninguna cuenta.',['setup']),
 lesson('Add workers','Agregar trabajadores','Add Jordan, then try the simulated CSV import. Duplicate imports are blocked. No file is uploaded.','Agrega a Jordan y prueba la importación CSV simulada. No se sube ningún archivo.',['add','csv']),
 lesson('Prepare invitations','Preparar invitaciones','Prepare the worker invitation, add the client and prepare its invitation. Then switch to each role to activate sample access. Nothing is sent.','Prepara las invitaciones y cambia a cada rol para activar su acceso de práctica. No se envía nada.',['invite','clientadd','clientinvite']),
 lesson('Create and assign shift','Crear y asignar turno','Activate the worker and client first. Create Warehouse A, 8 AM–4 PM, then assign Maria.','Primero activa el trabajador y el cliente. Crea el turno Warehouse A, 8 AM–4 PM, y asigna a Maria.',['shift','assign']),
 lesson('Reply inside the app','Responder dentro de la app','Add the prepared English reply. Its Spanish translation is a fixed training example, not automatic translation.','Agrega la respuesta preparada en inglés. La traducción es un ejemplo fijo, no traducción automática.',['messageEnglish']),
 lesson('Request coverage','Solicitar cobertura','This uses a separate fictional coverage shift; it does not alter Maria’s attendance exercise. Switch to Worker B to accept, then Client to confirm.','Este escenario de cobertura es separado. Cambia al trabajador B para aceptar y al cliente para confirmar.',['replacement','cancelReplacement']),
 lesson('Resolve time problem','Resolver problema de horas','After the worker clocks out and reports a Time Problem, resolve it here. Then ask the client to review attendance.','Después de la salida y el informe del trabajador, resuelve el problema aquí. Luego el cliente revisa la asistencia.',['resolve']),
 lesson('Archive sample record','Archivar registro de práctica','Archive only after clock-out and client review. This changes only the simulation and never deletes records.','Archiva solo después de la salida y revisión del cliente. Solo cambia la simulación; no elimina registros.',['archive'])],
worker:[
 lesson('Activate sample access','Activar acceso de práctica','The agency must prepare the sample invitation first. No real password or account is used.','La agencia prepara primero la invitación. No se usa una contraseña ni cuenta real.',['activateWorker']),
 lesson('Review your assignment','Revisar asignación','After the agency assigns Maria, acknowledge Warehouse A, 8 AM–4 PM.','Después de que la agencia asigne a Maria, confirma Warehouse A, 8 AM–4 PM.',['confirm']),
 lesson('On the way or delayed','En camino o con retraso','Practice both updates. Running Late uses a sample ETA of 8:20 AM.','Practica ambas actualizaciones. El retraso usa una hora estimada de 8:20 AM.',['way','late']),
 lesson('Arrive and clock in','Llegar y registrar entrada','Arrival is not clock-in. Record arrival, then clock in. This distinction must also be clear in the real app.','La llegada no es la entrada. Registra ambas acciones. La app real debe explicar esta diferencia.',['arrive','clockIn']),
 lesson('Break and photo proof','Descanso y foto','Start and end the break. Add simulated proof; no camera or actual photo is requested.','Inicia y termina el descanso. Agrega una prueba simulada; no se usa cámara ni foto real.',['break','back','photo']),
 lesson('Message the agency','Enviar mensaje a la agencia','Use the prepared Spanish late notice. The original and fixed English example stay visible. No real translation service runs.','Usa el aviso preparado en español. Se muestran el original y el ejemplo fijo en inglés. No se usa un servicio de traducción.',['messageSpanish']),
 lesson('Emergency and replacement','Emergencia y reemplazo','Emergency is only a staffing exercise, not an emergency-services channel. Accept as Jordan on the separate coverage request after it is opened.','Es una práctica de personal, no un servicio de emergencias. Acepta como Jordan después de abrir la solicitud separada.',['emergency','acceptReplacement']),
 lesson('Clock out and flag time','Registrar salida y problema','End your break first, clock out, then submit the sample Time Problem to the agency.','Termina el descanso, registra la salida y envía el problema de horas a la agencia.',['out','dispute'])],
client:[
 lesson('Activate sample access','Activar acceso de práctica','The agency prepares your client invitation first. Activating this role here is not a real permissions test.','La agencia prepara tu invitación. Activar este rol aquí no prueba permisos reales.',['activateClient']),
 lesson('Review assigned team','Revisar equipo asignado','Read the sample records below. The roster changes only inside this page; cross-user delivery must be tested separately.','Revisa los registros de abajo. Solo cambian en esta página; la entrega entre usuarios se prueba aparte.',[]),
 lesson('Review attendance','Revisar asistencia','Switch to Worker and send late, arrival, clock-in and break updates. Return here to compare the sample timeline.','Cambia a Trabajador y registra retraso, llegada, entrada y descanso. Vuelve y compara la cronología.',[]),
 lesson('Message agency','Enviar mensaje a la agencia','Send the prepared worksite instruction. This is sample text with a fixed Spanish translation.','Envía la instrucción preparada del lugar. Es texto de ejemplo con traducción fija al español.',['messageEnglish']),
 lesson('Request replacement','Solicitar reemplazo','Open a separate coverage request. Switch to Worker to accept as Jordan. Only one assignment may be created.','Abre una solicitud separada. Cambia a Trabajador para aceptar como Jordan. Solo se crea una asignación.',['replacement']),
 lesson('Confirm replacement','Confirmar reemplazo','Confirm after Jordan accepts. Repeated acceptance or confirmation must not create another assignment.','Confirma después de que Jordan acepte. Repetir no debe crear otra asignación.',['confirmReplacement']),
 lesson('Review completed time','Revisar horas completadas','The worker must clock out. If a time problem is open, the agency resolves it first. Then review attendance.','El trabajador registra la salida. La agencia resuelve problemas abiertos antes de revisar la asistencia.',['review'])]
};
const labels={setup:['Create sample agency','Crear agencia de práctica'],add:['Add Jordan Rivera','Agregar Jordan Rivera'],csv:['Simulate CSV import','Simular importación CSV'],invite:['Prepare worker invite','Preparar invitación de trabajador'],clientadd:['Add sample client','Agregar cliente de práctica'],clientinvite:['Prepare client invite','Preparar invitación de cliente'],activateWorker:['Activate sample worker','Activar trabajador de práctica'],activateClient:['Activate sample client','Activar cliente de práctica'],shift:['Create sample shift','Crear turno de práctica'],assign:['Assign Maria','Asignar a Maria'],confirm:['Acknowledge assignment','Confirmar asignación'],way:['On My Way','En camino'],late:['Running Late — ETA 8:20','Con retraso — llegada 8:20'],arrive:["I’ve Arrived","Ya llegué"],clockIn:['Clock In','Registrar entrada'],break:['Start Break','Iniciar descanso'],back:['Back from Break','Regresar del descanso'],photo:['Add sample photo proof','Agregar prueba fotográfica simulada'],messageSpanish:['Send sample Spanish message','Enviar mensaje de ejemplo en español'],messageEnglish:['Send sample English reply','Enviar respuesta de ejemplo en inglés'],emergency:['Simulate emergency absence','Simular ausencia de emergencia'],replacement:['Open sample coverage request','Abrir solicitud de cobertura'],cancelReplacement:['Cancel sample coverage request','Cancelar solicitud de cobertura'],acceptReplacement:['Accept as Worker B Jordan','Aceptar como trabajador B Jordan'],confirmReplacement:['Confirm replacement','Confirmar reemplazo'],out:['Clock Out','Registrar salida'],dispute:['Report sample Time Problem','Informar problema de horas'],resolve:['Resolve sample Time Problem','Resolver problema de horas'],review:['Review attendance','Revisar asistencia'],archive:['Archive sample shift','Archivar turno de práctica']};
const roleLabels={agency:['Agency Office','Agencia'],worker:['Temp Worker','Trabajador'],client:['Client Supervisor','Supervisor del cliente'],overview:['Full Journey','Recorrido completo']};
function feedback(text,isError=false){const el=document.getElementById('feedback');el.textContent=text;el.classList.toggle('error',isError);}
function run(action){const result=engine.transition(s,current,action);if(result.ok)s=result.state;draw();feedback(result.message[language==='es'?1:0],!result.ok);}
function reset(){if(!window.confirm(t('Reset only this page’s fictional practice progress? No real records will change.','¿Reiniciar solo el progreso ficticio de esta página? No cambiarán registros reales.')))return;s=engine.fresh();current='agency';step=0;draw();feedback(t('Practice reset. No real data changed.','Práctica reiniciada. No cambió ningún dato real.'));}
function readyScenario(){if(s.events.length&&!window.confirm(t('Replace this page’s sample progress with a ready-to-practice assignment?','¿Reemplazar el progreso de ejemplo con una asignación lista para practicar?')))return;
s=engine.fresh();for(const [r,a] of [['agency','setup'],['agency','add'],['agency','invite'],['agency','clientadd'],['agency','clientinvite'],['worker','activateWorker'],['client','activateClient'],['agency','shift'],['agency','assign']])s=engine.transition(s,r,a).state;step=0;draw();feedback(t('Fictional assignment loaded. Worker can now acknowledge it.','Asignación ficticia cargada. El trabajador puede confirmarla.'));}
function draw(){
document.documentElement.lang=language;
document.querySelectorAll('[data-role]').forEach(b=>{b.classList.toggle('active',b.dataset.role===current);b.setAttribute('aria-pressed',b.dataset.role===current?'true':'false');b.textContent=roleLabels[b.dataset.role][language==='es'?1:0]});
document.querySelectorAll('[data-action="reset"]').forEach(b=>b.textContent=t('Restart practice','Reiniciar práctica'));
document.getElementById('readyScenario').textContent=t('Load ready practice assignment','Cargar asignación de práctica');
document.getElementById('practice-notice').textContent=t('PRACTICE ONLY. Fictional data stays in this page’s memory. No accounts, messages, files, invitations, payments or SMS are sent. Refresh resets practice. Role switching is not authentication.','SOLO PRÁCTICA. Los datos ficticios quedan en la memoria de esta página. No se envían cuentas, mensajes, archivos, invitaciones, pagos ni SMS. Recargar reinicia la práctica. Cambiar de rol no es autenticación.');
document.getElementById('role-intro').textContent=t('Explore lessons in any order. Actions check prerequisites; clicking Next never counts as completing an action.','Explora lecciones en cualquier orden. Las acciones verifican requisitos; Siguiente no completa una acción.');
const overview=current==='overview';const list=overview?[]:lessons[current];
document.getElementById('step-list').innerHTML=list.map((l,i)=>`<button class="${step===i?'active':''}" data-step="${i}" aria-current="${step===i?'step':'false'}">${i+1}. ${esc(language==='es'?l.es:l.en)}</button>`).join('');
if(overview){document.getElementById('lesson').innerHTML=`<h2>${t('The connected journey','El recorrido conectado')}</h2><ol><li>${t('Agency prepares sample people and invitations.','La agencia prepara personas e invitaciones de práctica.')}</li><li>${t('Worker and client activate sample access.','Trabajador y cliente activan acceso de práctica.')}</li><li>${t('Agency assigns; worker reports attendance.','La agencia asigna; el trabajador registra asistencia.')}</li><li>${t('Separate replacement request: open → worker acceptance → client confirmation.','Solicitud separada: abrir → aceptación del trabajador → confirmación del cliente.')}</li><li>${t('Clock out → time problem → agency resolution → client review → archive.','Salida → problema de horas → resolución → revisión del cliente → archivo.')}</li></ol><p>${t('This demonstrates sequence, not live delivery or production readiness.','Esto demuestra la secuencia, no la entrega real ni la preparación para producción.')}</p>`;}
else{const l=list[step];const completed=a=>s.events.some(e=>e.role===current&&e.action===a);const done=l.actions.filter(completed).length;document.getElementById('lesson').innerHTML=`<span class="tag">${t('Lesson','Lección')} ${step+1} / ${list.length}</span><h2>${esc(language==='es'?l.es:l.en)}</h2><div class="help">${esc(language==='es'?l.helpEs:l.helpEn)}</div><p>${l.actions.length?t('Actions recorded in this role','Acciones registradas en este rol')+': '+done:t('Observation exercise; no completion claim.','Ejercicio de observación; no se declara completado.')}</p><p class="sub">${t('Alternative actions are optional; you do not need to complete every button.','Las alternativas son opcionales; no necesitas completar todos los botones.')}</p><div class="actions">${l.actions.map(a=>`<button data-action="${a}">${esc(labels[a][language==='es'?1:0])}${completed(a)?' ✓':''}</button>`).join('')}</div><div class="actions"><button class="secondary" data-nav="-1" ${step===0?'disabled':''}>${t('Previous','Anterior')}</button><button class="next" data-nav="1" ${step===list.length-1?'disabled':''}>${t('Next lesson','Siguiente lección')}</button></div>`;}
const statusLabels={scheduled:['Scheduled','Programado'],on_way:['On my way','En camino'],late:['Running late','Con retraso'],arrived:['Arrived, not clocked in','Llegó, sin entrada'],working:['Working','Trabajando'],break:['On break','En descanso'],out:['Clocked out','Salida registrada']};
const records=[[t('Workers','Trabajadores'),s.workers.length],[t('Assigned','Asignado'),s.assigned?'Maria Lopez':'—'],[t('Attendance','Asistencia'),statusLabels[s.status][language==='es'?1:0]],[t('ETA','Llegada estimada'),s.eta||'—'],[t('Replacement','Reemplazo'),s.replacement],[t('Replacement shifts','Turnos de reemplazo'),s.replacementShifts],[t('Time problem','Problema de horas'),s.dispute],[t('Archived','Archivado'),s.archived?t('Yes','Sí'):t('No','No')]];
document.getElementById('snapshot').innerHTML=records.map(([k,v])=>`<div><small>${esc(k)}</small><b>${esc(v)}</b></div>`).join('');
document.getElementById('messages').innerHTML=`<p class="sub">${t('Prepared translations only. No automatic translation or external delivery.','Solo traducciones preparadas. Sin traducción automática ni entrega externa.')}</p>`+s.messages.map(m=>`<div class="event"><b>${esc(m.from)} → ${esc(m.to)}</b><p>${esc(m.original)}</p><p>${t('Sample translation','Traducción de ejemplo')}: ${esc(m.translation)}</p></div>`).join('');
document.getElementById('events').innerHTML=s.events.length?s.events.map(e=>`<div class="event"><strong>${esc(roleLabels[e.role][language==='es'?1:0])}</strong>: ${esc(e.text[language==='es'?1:0])}</div>`).join(''):`<p>${t('No simulated actions yet.','Aún no hay acciones simuladas.')}</p>`;
}
document.addEventListener('click',e=>{const role=e.target.closest('[data-role]');if(role){current=role.dataset.role;step=0;draw();feedback('');return;}const nav=e.target.closest('[data-nav]');if(nav&&current!=='overview'){step=Math.max(0,Math.min(lessons[current].length-1,step+Number(nav.dataset.nav)));draw();feedback('');return;}const lessonButton=e.target.closest('[data-step]');if(lessonButton){step=Number(lessonButton.dataset.step);draw();feedback('');return;}const action=e.target.closest('[data-action]');if(action){if(action.dataset.action==='reset')reset();else run(action.dataset.action);}});
document.getElementById('language').addEventListener('change',e=>{language=e.target.value==='es'?'es':'en';draw();feedback('');});
document.getElementById('readyScenario').addEventListener('click',readyScenario);
draw();
})();
